<?php
namespace Tests\Feature;use Tests\TestCase;
final class FinalMissingItemsClosureTest extends TestCase{
 public function test_business_login_uses_central_b2b_configuration_and_never_crm():void{$view=file_get_contents(resource_path('views/landing/empresas.blade.php'));$domains=file_get_contents(config_path('zigo_domains.php'));$this->assertStringContainsString("config('zigo_domains.portals.b2b.login_url')",$view);$this->assertStringNotContainsString("route('crm.login')",$view);$this->assertStringContainsString("env('ZIGO_B2B_URL')",$domains);$this->assertStringContainsString("'https://empresas.zigo-envios.com'",$domains);$this->assertStringContainsString("'/negocios/login'",$domains);foreach([resource_path('views/index.blade.php'),resource_path('views/landing/empresas.blade.php')] as $file)$this->assertDoesNotMatchRegularExpression('/(?:Soluciones Empresas|solución empresarial|Iniciar sesión)[\s\S]{0,180}(?:crm\/login|crm\.login)/i',file_get_contents($file));}
 public function test_payment_export_reuses_xlsx_writer_and_contains_no_internal_data():void{$controller=file_get_contents(app_path('Http/Controllers/CRM/CrmPaymentExportController.php'));$this->assertStringContainsString('SimpleXlsxWriter',$controller);foreach(['provider_base_price','provider_total','zigo_margin','guia_response_snapshot','payment_verification_payload','token'] as $secret)$this->assertStringNotContainsString($secret,$controller);$view=file_get_contents(resource_path('views/crm/payments/index.blade.php'));$this->assertStringContainsString('Exportar resultados',$view);$this->assertStringContainsString('Exportar todos',$view);}
 public function test_payment_export_route_is_inside_protected_crm_group():void{$route=collect(app('router')->getRoutes())->first(fn($r)=>$r->getName()==='crm.pagos.export');$this->assertNotNull($route);$middleware=$route->gatherMiddleware();$this->assertContains('auth',$middleware);$this->assertContains('roles:sysadmin,admin',$middleware);}
}
